// Functional tests of Review (#16, PRD 4.5.3, F13) through the HTTP API: today's queue, rating with FSRS, the
// daily new-Card limit and the day boundary at 00:00 Asia/Shanghai. Cards are made with POST /cards on a Book
// generated by playing the worker over /internal.
import { eq } from "drizzle-orm";
import { describe, expect, it } from "vitest";
import { DAILY_NEW_CARDS, type Card, type ReviewCount, type ReviewQueue } from "../src/contract.js";
import { allowlist, cards } from "../src/db/schema.js";
import { generatedBook, logIn, testApp, withCookie, type TestApp } from "./helpers.js";
import { fakeTsSegment } from "./ts-fixture.js";

type T = Awaited<ReturnType<typeof testApp>>;

const MINUTE = 60_000;
const DAY = 24 * 60 * MINUTE;
/** 30 distinct words, one word Card each. */
const WORDS = Array.from({ length: 30 }, (_, i) => `word${String.fromCharCode(97 + (i % 26))}${i >= 26 ? "z" : ""}`);
const SENTENCE = `${WORDS.join(" ")}.`;

interface Setup extends T {
  sentenceId: string;
}

async function setUp(): Promise<Setup> {
  const t = await testApp();
  const book = await generatedBook(
    t,
    "Pride and Prejudice",
    [{ title: "I", sentences: [{ paragraphIndex: 0, text: SENTENCE, spokenText: SENTENCE }] }],
    (_s, durationMs) => fakeTsSegment(durationMs, 1),
  );
  const [sentence] = (await (await t.app.request(`/api/chapters/${book.chapters[0]!.id}/sentences`)).json()) as { id: string }[];
  return { ...t, sentenceId: sentence!.id };
}

/** Makes a word Card of WORDS[i], one second after the previous one (so they order by creation). */
async function makeCard(t: Setup, i: number, app: TestApp = t.app): Promise<Card> {
  t.clock.advance(1000);
  const start = SENTENCE.indexOf(WORDS[i]!);
  const res = await app.request("/api/cards", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ sentenceId: t.sentenceId, start, end: start + WORDS[i]!.length }),
  });
  expect(res.status).toBe(201);
  return (await res.json()) as Card;
}

async function makeCards(t: Setup, n: number): Promise<Card[]> {
  const made: Card[] = [];
  for (let i = 0; i < n; i++) made.push(await makeCard(t, i));
  return made;
}

async function queue(app: TestApp): Promise<ReviewQueue["cards"]> {
  const res = await app.request("/api/review");
  expect(res.status).toBe(200);
  return ((await res.json()) as ReviewQueue).cards;
}

async function count(app: TestApp): Promise<number> {
  const res = await app.request("/api/review/count");
  expect(res.status).toBe(200);
  return ((await res.json()) as ReviewCount).count;
}

function rate(app: TestApp, cardId: string, rating: number) {
  return app.request(`/api/cards/${cardId}/review`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ rating }),
  });
}

async function rated(app: TestApp, cardId: string, rating: number): Promise<ReviewQueue["cards"]> {
  const res = await rate(app, cardId, rating);
  expect(res.status).toBe(200);
  return ((await res.json()) as ReviewQueue).cards;
}

async function dueOf(t: Setup, cardId: string): Promise<number> {
  const [row] = await t.db.select({ due: cards.due }).from(cards).where(eq(cards.id, cardId));
  return row!.due.getTime();
}

describe("GET /api/review (今日队列, PRD 4.5.3)", () => {
  it("holds new Cards by due date with each rating's next interval, and counts them for the navigation", async () => {
    const t = await setUp();
    const made = await makeCards(t, 3);

    const items = await queue(t.app);

    expect(items.map((i) => i.card)).toEqual(made);
    for (const { intervalsMs } of items) {
      expect(intervalsMs).toHaveLength(4);
      // 忘了 < 困难 < 记得 < 简单, the first ones minutes (learning steps), 简单 at least a day.
      expect([...intervalsMs].sort((a, b) => a - b)).toEqual(intervalsMs);
      expect(intervalsMs[0]).toBe(MINUTE);
      expect(intervalsMs[3]).toBeGreaterThanOrEqual(DAY);
    }
    expect(await count(t.app)).toBe(3);
  });

  it("takes in at most 20 new Cards a day, the earliest made first (AC-REV-04)", async () => {
    const t = await setUp();
    const made = await makeCards(t, 30);

    const items = await queue(t.app);

    expect(items.map((i) => i.card.id)).toEqual(made.slice(0, DAILY_NEW_CARDS).map((c) => c.id));
    expect(await count(t.app)).toBe(DAILY_NEW_CARDS);
  });

  it("goes on with the rest after leaving mid-way: rated new Cards count toward the day's limit (AC-REV-05)", async () => {
    const t = await setUp();
    const made = await makeCards(t, 30);
    for (const card of made.slice(0, 5)) await rated(t.app, card.id, 4);

    const items = await queue(t.app);

    // 简单 schedules them days away; the day's limit has 15 new Cards left, the next ones by creation.
    expect(items.map((i) => i.card.id)).toEqual(made.slice(5, DAILY_NEW_CARDS).map((c) => c.id));
    expect(await count(t.app)).toBe(DAILY_NEW_CARDS - 5);
    // 【今日复习完成】 counts what was rated before leaving too.
    expect(((await (await t.app.request("/api/review")).json()) as ReviewQueue).reviewedToday).toBe(5);
  });

  it("starts a new day at 00:00 Asia/Shanghai: a fresh new-Card limit, and Cards due by the day's end", async () => {
    const t = await setUp();
    const made = await makeCards(t, 25);
    const easy = made[0]!;
    for (const card of made.slice(0, DAILY_NEW_CARDS)) await rated(t.app, card.id, 4);
    expect(await queue(t.app)).toEqual([]);
    const easyDue = await dueOf(t, easy.id);

    // 2026-11-18T15:59Z is 23:59 in Shanghai: still the same day.
    t.clock.advance(Date.parse("2026-11-18T15:59:00Z") - t.clock.now().getTime());
    expect(await count(t.app)).toBe(0);
    // 16:00Z is 00:00 the next day there: the 5 new Cards left come in, and nothing is rated yet that day.
    t.clock.advance(MINUTE);
    expect(((await (await t.app.request("/api/review")).json()) as ReviewQueue).reviewedToday).toBe(0);
    expect((await queue(t.app)).map((i) => i.card.id)).toEqual(made.slice(DAILY_NEW_CARDS).map((c) => c.id));
    for (const card of made.slice(DAILY_NEW_CARDS)) await rated(t.app, card.id, 4);

    // The day the Cards rated 简单 fall due, they are in the queue from its start, ahead of new ones made later.
    t.clock.advance(easyDue - t.clock.now().getTime());
    const later = await makeCard(t, 29);
    const items = await queue(t.app);
    expect(items[0]!.card.id).toBe(easy.id);
    expect(items.at(-1)!.card.id).toBe(later.id);
  });

  it("leaves out deleted Cards and other users' Cards", async () => {
    const t = await setUp();
    const [kept, deleted] = await makeCards(t, 2);
    await t.db.delete(cards).where(eq(cards.id, deleted!.id));
    await t.db.insert(allowlist).values({ email: "other@example.com" });
    const other = withCookie(t.anon, await logIn(t, "other@example.com"));

    expect((await queue(t.app)).map((i) => i.card.id)).toEqual([kept!.id]);
    expect(await queue(other)).toEqual([]);
    expect(await count(other)).toBe(0);
    expect((await rate(other, kept!.id, 3)).status).toBe(404);
    expect((await rate(t.app, deleted!.id, 3)).status).toBe(404);
  });
});

describe("POST /api/cards/{id}/review (自评, PRD 4.5.3)", () => {
  it("schedules the Card by the interval its button showed and answers with the queue after it (AC-REV-03)", async () => {
    const t = await setUp();
    const [first, second] = await makeCards(t, 2);
    const [shown] = await queue(t.app);
    t.clock.advance(5000);
    const ratedAt = t.clock.now().getTime();

    const after = await rated(t.app, first!.id, 3);

    expect(await dueOf(t, first!.id)).toBe(ratedAt + shown!.intervalsMs[2]!);
    expect(after[0]!.card.id).toBe(second!.id);
    // 记得 on a new Card is a learning step minutes away: still due today, so it comes again after the others.
    expect(after.map((i) => i.card.id)).toEqual([second!.id, first!.id]);
    expect(after[1]!.card.due).toBe(new Date(ratedAt + shown!.intervalsMs[2]!).toISOString());
  });

  it("moves the Card days away with 简单, out of today's queue", async () => {
    const t = await setUp();
    const [card] = await makeCards(t, 1);
    const [shown] = await queue(t.app);
    const ratedAt = t.clock.now().getTime();

    expect(await rated(t.app, card!.id, 4)).toEqual([]);
    expect(await dueOf(t, card!.id)).toBe(ratedAt + shown!.intervalsMs[3]!);
    expect(await count(t.app)).toBe(0);
  });

  it("brings a Card rated 忘了 back a minute later, and a lapse in review back to relearning", async () => {
    const t = await setUp();
    const [card] = await makeCards(t, 1);
    await rated(t.app, card!.id, 4);
    t.clock.advance((await dueOf(t, card!.id)) - t.clock.now().getTime());

    const [again] = await rated(t.app, card!.id, 1);

    expect(again!.card.id).toBe(card!.id);
    expect(Date.parse(again!.card.due)).toBe(t.clock.now().getTime() + 10 * MINUTE);
    const [row] = await t.db.select().from(cards).where(eq(cards.id, card!.id));
    expect(row).toMatchObject({ state: "relearning", lapses: 1, reps: 2 });
  });

  it("refuses a rating outside 1 to 4", async () => {
    const t = await setUp();
    const [card] = await makeCards(t, 1);

    for (const rating of [0, 5, 2.5]) expect((await rate(t.app, card!.id, rating)).status).toBe(400);
    expect(await count(t.app)).toBe(1);
  });

  it("needs a session", async () => {
    const t = await setUp();
    expect((await t.anon.request("/api/review")).status).toBe(401);
    expect((await t.anon.request("/api/review/count")).status).toBe(401);
  });
});
